// Frontend sending a Request Body
fetch('https://api.com/users', {
  method: 'POST',
  // CRITICAL: Tell the server this is JSON!
  headers: { 'Content-Type': 'application/json' },
  // The BODY must be converted to a string before sending over the network
  body: JSON.stringify({
    username: "johndoe",
    password: "secret123",
    preferences: { theme: "dark" }
  })
});

// Backend receiving the Request Body (Express.js)
// Note: You must use app.use(express.json()) middleware for this to work!
app.post('/users', (req, res) => {
  const username = req.body.username; // "johndoe"
  const theme = req.body.preferences.theme; // "dark"
});
